// Event descriptor unit test (hle_net.c, nn::socket::EventFd): the counter as FreeBSD's eventfd, Poll on it, a write from another thread waking a poller, Close, and every other
// descriptor still failing. Expected values are hand-written from eventfd(2), not generated by the implementation.
#include "../hle_net.c"
#include <time.h>
uint64_t now_ns(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return (uint64_t)t.tv_sec * 1000000000u + (uint64_t)t.tv_nsec; }
int dm_detclock_enabled(void) { return 0; }
void dm_guest_sleep_ns(int64_t ns) { struct timespec t = {(time_t)(ns / 1000000000), (long)(ns % 1000000000)}; nanosleep(&t, 0); }
static int checks, fails;
#define CHECK(c, s) do { checks++; int ok = !!(c); fails += !ok; printf("%s %s\n", ok ? "✓" : "✗", s); } while (0)
static int g_wfd;
static void *late_write(void *p) { (void)p; dm_guest_sleep_ns(30000000); h_sk_EventFdWrite(g_wfd, 1); return NULL; }
int main(void) {
    unsigned long v = 99;
    int a = h_sk_EventFd(0, SK_EFD_NONBLOCK | 2);   // gRPC's EventFd(0, 6)
    CHECK(a >= 0, "EventFd(0, 6) gives a descriptor");
    CHECK(h_sk_EventFdRead(a, &v) == -1 && h_sk_GetLastError() == SK_EAGAIN && v == 99, "non-blocking read at 0: -1, EAGAIN, the value untouched");
    sk_pollfd p[2] = {{a, SK_POLLIN | SK_POLLOUT, 0}, {-1, SK_POLLIN, 7}};
    CHECK(dm_sk_poll(p, 2, 0) == 1 && p[0].revents == SK_POLLOUT && p[1].revents == 0, "Poll at 0: writable only; a negative descriptor is skipped");
    CHECK(h_sk_EventFdWrite(a, 2) == 0 && h_sk_EventFdWrite(a, 3) == 0, "two writes");
    p[0].events = SK_POLLIN;
    CHECK(dm_sk_poll(p, 1, 0) == 1 && p[0].revents == SK_POLLIN, "Poll after the writes: readable");
    CHECK(h_sk_EventFdRead(a, &v) == 0 && v == 5, "read takes the sum, 5");
    CHECK(dm_sk_poll(p, 1, 0) == 0 && p[0].revents == 0, "Poll after the read: nothing ready, 0");
    int s = h_sk_EventFd(2, SK_EFD_SEMAPHORE | SK_EFD_NONBLOCK);
    CHECK(h_sk_EventFdRead(s, &v) == 0 && v == 1 && h_sk_EventFdRead(s, &v) == 0 && v == 1 && h_sk_EventFdRead(s, &v) == -1, "semaphore: 1 per read, then EAGAIN");
    g_wfd = a; pthread_t t; pthread_create(&t, NULL, late_write, NULL);
    uint64_t t0 = now_ns(); int r = dm_sk_poll(p, 1, 2000); uint64_t dt = now_ns() - t0;
    pthread_join(t, NULL);
    CHECK(r == 1 && p[0].revents == SK_POLLIN && dt < 1000000000u, "a write from another thread wakes a waiting Poll before its timeout");
    t0 = now_ns(); h_sk_EventFdRead(a, &v); r = dm_sk_poll(p, 1, 50); dt = now_ns() - t0;
    CHECK(r == 0 && dt >= 45000000u, "Poll with nothing written waits out its 50 ms timeout, 0");
    CHECK(h_sk_Fcntl(a, SK_F_GETFL, 0) == SK_O_NONBLOCK && h_sk_Fcntl(a, SK_F_SETFL, 0) == 0 && h_sk_Fcntl(a, SK_F_GETFL, 0) == 0, "fcntl F_GETFL / F_SETFL on an event descriptor");
    CHECK(h_sk_Close(a) == 0 && h_sk_Close(a) == -1 && h_sk_EventFdWrite(a, 1) == -1, "Close frees it; a closed descriptor fails");
    sk_pollfd q = {3, SK_POLLIN, 0};
    CHECK(dm_sk_poll(&q, 1, 0) == -1 && h_sk_GetLastError() == SK_ENETDOWN && h_sk_Close(3) == -1, "any other descriptor still fails with ENETDOWN");
    h_sk_Close(s);
    printf("t_net: %d/%d\n", checks - fails, checks);
    return fails != 0;
}
